  ('English'),
  ('Filipino'),
  ('MAPEH'),
  ('Mathematics'),
  ('Science'),
  ('TLE: AFA - Agricultural Crop Production'),
  ('TLE: AFA - Animal Production'),
  ('TLE: AFA - Aquaculture (Fish Culture)'),
  ('Values Education')
ON CONFLICT ((lower(btrim(name)))) DO NOTHING;

